class Student:
    def __init__(self, name, subjects):
        self.name = name
        self.subjects = subjects

    def calculate_average(self):
        return sum(self.subjects.values()) / len(self.subjects)

    def evaluate_performance(self):
        average = self.calculate_average()
        if average >= 80:
            return "Excellent"
        elif average >= 60:
            return "Good"
        else:
            return "Needs Improvement"

class School:
    def __init__(self):
        self.students = {}

    def add_student(self, name, subjects):
        self.students[name] = Student(name, subjects)

    def evaluate_all_students(self):
        for student in self.students.values():
            print(f"{student.name}: {student.evaluate_performance()}")

# Example usage
school = School()
school.add_student("John", {"Math": 90, "Science": 85, "English": 95})
school.add_student("Jane", {"Math": 70, "Science": 80, "English": 90})

school.evaluate_all_students()
```
